css:
:root{--paper:#f5f3ea;--ink:#242c26;--muted:#636b62;--line:#d8dcd0;--green:#245b46;--mint:#dce9dc;--rose:#f0d5cd;--amber:#f4e5bf;--white:#fffef8;--radius:18px;color-scheme:light;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:var(--paper)}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button,select{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #9c4d31;outline-offset:4px}button{min-height:44px}button:disabled{cursor:not-allowed;opacity:.52}a{color:inherit}button,input,select{border-radius:8px}button{border:0}input[type=text],select{border:1px solid #a5afa2;background:var(--white);color:var(--ink);padding:12px}input[type=checkbox]{width:18px;height:18px;accent-color:var(--green)}[hidden]{display:none!important}.masthead{padding:26px 4.5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.wordmark{display:flex;align-items:center;gap:12px;font-weight:800;letter-spacing:2px;font-size:17px;text-decoration:none}.mark{font-size:29px;line-height:1;width:38px;height:38px;display:inline-flex;align-items:center;background:var(--green);color:var(--paper);padding-left:6px;position:relative}.mark span{position:absolute;font-size:18px;top:2px;right:2px}.edition{font-size:10px;letter-spacing:1.7px;font-weight:700;display:flex;gap:30px}.edition span{color:var(--muted)}main{max-width:1300px;margin:auto;padding:0 4%}.intro{padding:54px 0 44px;max-width:820px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:2px;color:var(--green);margin:0 0 15px}h1{font-size:clamp(40px,5.4vw,68px);line-height:1.05;letter-spacing:-2.7px;margin:0;font-weight:650}h1 em{font-family:Georgia,'Times New Roman',serif;font-weight:400;color:var(--green);letter-spacing:-2.1px}.lede{max-width:630px;line-height:1.65;color:var(--muted);font-size:17px;margin:24px 0 0}.workspace{border-top:2px solid var(--ink);padding-top:24px}.toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px}.case-picker label{display:block;font-size:11px;letter-spacing:1px;font-weight:700;text-transform:uppercase;margin-bottom:8px}.case-picker select{min-width:280px;max-width:100%;font-size:14px;padding-right:30px}.tabs{display:flex;border:1px solid var(--line);padding:4px;border-radius:12px;background:#ebece2;gap:4px}.tabs button{padding:10px 20px;background:transparent;font-weight:700;font-size:13px;color:var(--muted)}.tabs button[aria-selected=true]{background:var(--green);color:white;box-shadow:0 1px 3px #0002}.episode-heading{display:flex;justify-content:space-between;gap:24px;padding:33px 0 24px;align-items:start}.episode-heading h2{font-family:Georgia,'Times New Roman',serif;font-size:31px;font-weight:400;margin:0 0 10px;letter-spacing:-.6px}.episode-heading p:not(.eyebrow){max-width:720px;font-size:14px;line-height:1.7;color:var(--muted);margin:0}.episode-heading .eyebrow{margin-bottom:8px;font-size:10px}.revision{font-size:11px;white-space:nowrap;line-height:1.8;border:1px solid var(--line);border-radius:20px;padding:5px 12px;margin-top:24px}.workbench-grid{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);gap:22px}.panel{border:1px solid var(--line);background:var(--white);border-radius:var(--radius);padding:27px;min-width:0}.results{background:#edf1e8}.section-title{display:flex;gap:13px;align-items:flex-start;margin-bottom:24px}.step{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;background:var(--ink);border-radius:50%;width:27px;height:27px;font-size:10px;color:white;font-weight:bold}.section-title h3,h3{font-size:19px;font-weight:600;margin:0 0 7px;letter-spacing:-.4px}.section-title p{font-size:12px;color:var(--muted);margin:0;line-height:1.6}h4{font-size:12px;text-transform:uppercase;letter-spacing:.9px;margin:0 0 12px}.cards-editor{display:grid;grid-template-columns:1fr 1fr;gap:12px}.label-card{border:1px solid var(--line);border-radius:12px;padding:15px;background:#faf8ef}.label-card:nth-child(2){background:#eaf0e5}.label-card:nth-child(3){background:#f5e8df}.label-card:nth-child(4){background:#e8edf1}.card-top{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.7px;align-items:center;margin-bottom:10px}.card-initial{border:1px solid #aaa9;width:29px;height:29px;display:flex;align-items:center;justify-content:center;font-family:Georgia,serif;font-size:17px;color:var(--ink);background:#fff8;border-radius:50%}.label-card label{display:block;font-size:11px;color:var(--muted);margin-bottom:6px}.label-card input{display:block;width:100%;font-size:18px;padding:9px;background:#fff9;border-color:#aeb8aa}.label-card input:disabled{color:var(--muted);background:#e8e8df;cursor:not-allowed}.toggle{display:flex;align-items:center;gap:9px;margin-top:21px;font-size:13px;font-weight:600}.small{font-size:11px;color:var(--muted);line-height:1.6;margin:8px 0 0}.clue-section{border-top:1px solid var(--line);padding-top:21px;margin-top:21px}.clues{margin:0;padding-left:21px;color:var(--ink);font-size:14px;line-height:1.7}.clues li{padding-left:5px;margin-bottom:9px}.clues li::marker{font-size:11px;color:var(--green);font-weight:700}.change-note{margin-top:23px;font-size:13px;border-top:1px solid var(--line);padding-top:15px;line-height:1.65}.change-note summary{cursor:pointer;font-weight:600}.change-note ul{padding-left:18px;color:var(--muted)}.result-state{border-radius:11px;padding:17px;background:var(--amber);margin-bottom:20px}.result-state.verified{background:#d5e7d8}.result-state.action-mismatch,.result-state.inconsistent{background:var(--rose)}.result-state.invalid{background:var(--rose)}.result-state h4{font-size:15px;text-transform:none;letter-spacing:-.2px;margin:0 0 7px}.result-state p{font-size:13px;line-height:1.6;margin:0}.metrics{display:grid;grid-template-columns:1fr 1fr 1fr;border-top:1px solid #cbd3c6;border-bottom:1px solid #cbd3c6;margin:0 0 20px;padding:17px 0;gap:12px}.metric strong{display:block;font-family:Georgia,serif;font-size:31px;font-weight:400;margin-bottom:6px}.metric span{font-size:10px;line-height:1.5;display:block;color:var(--muted)}.path{font-size:12px;line-height:1.8;color:var(--muted);margin:0 0 7px;overflow-wrap:anywhere}.token-row{display:flex;gap:14px;align-items:baseline;padding:12px 0}.token{font-family:Georgia,serif;font-size:35px;letter-spacing:4px;color:var(--green)}.expected{font-size:11px;color:var(--muted);line-height:1.6}.witness{border-left:3px solid #a66b35;padding:4px 0 4px 12px;margin:17px 0}.witness h4{font-size:12px;text-transform:none;letter-spacing:0;margin:0 0 5px}.witness p{font-size:12px;line-height:1.6;margin:0}.primary{background:var(--green);color:#fff;display:inline-flex;align-items:center;justify-content:center;gap:24px;padding:13px 20px;font-weight:700;font-size:13px}.results>.primary{margin-top:15px;width:100%}.primary:hover{background:#173f30}.secondary{background:var(--ink);color:white;padding:13px 19px;font-weight:700;font-size:12px}.text-button{background:transparent;color:var(--green);text-decoration:underline;text-underline-offset:4px;font-size:12px;padding:10px 4px}.evidence-note{margin-top:24px;padding-top:19px;border-top:1px solid #cbd3c6}.evidence-note h4{font-size:10px}.evidence-note p{font-size:11px;line-height:1.7;color:var(--muted);margin:6px 0}.export-strip{display:flex;justify-content:space-between;gap:25px;padding:28px 5px;margin-top:12px;align-items:center;border-bottom:1px solid var(--line)}.export-strip h3{font-size:18px}.export-strip p{font-size:12px;color:var(--muted);line-height:1.65;max-width:650px;margin:5px 0}.export-strip .digest{font-family:monospace;font-size:9px;overflow-wrap:anywhere;word-break:break-all;max-width:560px;min-height:16px}.export-actions{display:flex;flex-direction:column;align-items:stretch;flex-shrink:0}.notice{font-size:13px;line-height:1.6;margin:15px 0;min-height:21px;color:var(--green)}.notice.error{color:#8d3528}.play-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.player-order{padding:0;list-style:none;margin:0}.player-order li{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:#f1f0e7;margin-bottom:9px;min-height:62px}.position{font-size:10px;color:var(--muted);width:18px}.keeper-label{font-family:Georgia,serif;font-size:23px;flex:1;overflow-wrap:anywhere}.move-button{background:white;border:1px solid var(--line);width:40px;flex-shrink:0;color:var(--green)}.player-controls{display:flex;justify-content:space-between;gap:12px}.hints p{font-size:13px;line-height:1.7;padding:13px;background:var(--amber);border-radius:9px;margin-bottom:0}.answer-row{display:flex;gap:10px;margin-top:9px}.answer-row input{min-width:0;flex:1}.answer-row .primary{flex-shrink:0}#answer-form{margin-top:30px}#answer-label{font-size:13px;font-weight:600}.feedback{min-height:38px;font-size:13px;line-height:1.65;color:var(--green)}#reveal{margin-top:12px;border-top:1px solid var(--line);padding-top:18px}.reveal-note{font-size:12px;line-height:1.65;color:var(--muted)}footer{display:flex;justify-content:space-between;padding:27px 4.5%;max-width:1400px;margin:20px auto 0;font-size:10px;letter-spacing:1px;color:var(--muted);gap:25px;line-height:1.7}.footer-dot{font-size:7px;padding:0 7px;color:var(--green)}@media(max-width:800px){.edition{display:none}.masthead{padding:21px 5%}main{padding:0 5%}.intro{padding:37px 0 32px}h1{font-size:49px;letter-spacing:-2px}.lede{font-size:15px}.toolbar{align-items:stretch;flex-direction:column;gap:18px}.case-picker select{width:100%;min-width:0}.tabs{align-self:stretch}.tabs button{flex:1;padding:9px 10px}.workbench-grid,.play-grid{grid-template-columns:1fr}.episode-heading{padding:27px 0 20px}.episode-heading h2{font-size:28px}.episode-heading p:not(.eyebrow){font-size:13px}.episode-heading .revision{margin-top:20px;font-size:10px}.panel{padding:22px}.export-strip{flex-direction:column;align-items:stretch;padding:25px 1px;gap:15px}.export-actions{align-items:stretch}.digest{max-width:100%!important}footer{flex-direction:column;gap:5px;padding:20px 5%}.cards-editor{gap:10px}.label-card{padding:12px}.metrics{gap:10px}.metric strong{font-size:29px}}@media(max-width:380px){h1{font-size:42px}.panel{padding:18px}.card-top{font-size:9px;letter-spacing:0}.label-card input{font-size:16px}.answer-row{flex-direction:column}.episode-heading{gap:10px}.revision{padding:4px 8px}}

/* Typed clue authoring and source/adaptation comparison. */
textarea{font:inherit;resize:vertical;width:100%;min-height:110px;border:1px solid #a5afa2;border-radius:8px;padding:12px;background:var(--white);color:var(--ink);line-height:1.6}textarea:focus-visible{outline:3px solid #9c4d31;outline-offset:4px}.clue-editor{display:grid;gap:12px;margin-top:18px}.clue-row{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:14px;background:#f2f1e8;border:1px solid var(--line);border-radius:10px;min-width:0}.clue-number{grid-column:1/-1;font-size:10px;letter-spacing:1px;font-weight:bold;text-transform:uppercase;color:var(--green)}.clue-row label{display:flex;flex-direction:column;gap:5px;font-size:10px;color:var(--muted);min-width:0}.clue-row label:nth-of-type(2){grid-column:1/-1;grid-row:3}.clue-row select{font-size:12px;padding:10px;width:100%;min-width:0}.clue-row button{justify-self:end;grid-column:1/-1;padding:3px 5px;min-height:34px}.hint-editing{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:12px;line-height:1.6}.hint-editing summary{cursor:pointer;font-weight:600;margin-bottom:12px}.hint-editing label{display:block;margin:9px 0}.comparison{margin-top:22px;background:#f9f8f1}.comparison-toolbar{display:flex;align-items:end;justify-content:space-between;gap:20px}.comparison-toolbar .case-picker{min-width:0;max-width:70%}.comparison-toolbar select{max-width:100%;min-width:0;width:100%}.comparison-pair{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin:22px 0 26px}.comparison-pair article{padding:20px;border:1px solid var(--line);border-radius:12px;background:#f0f1e8;min-width:0}.comparison-pair article:nth-child(2){background:#eaf1e8}.comparison-pair h4{text-transform:none;letter-spacing:0;font-family:Georgia,serif;font-size:22px;line-height:1.35;margin:0}.comparison-pair .eyebrow{font-size:10px;margin-bottom:9px}.comparison-words{font-size:14px;font-weight:600;line-height:1.6;overflow-wrap:anywhere}.mapping-editor{margin:15px 0 24px;display:grid;gap:9px}.mapping-row{display:grid;grid-template-columns:minmax(0,1fr) 24px minmax(0,1fr);gap:12px;align-items:center;padding:12px 15px;border:1px solid var(--line);border-radius:9px;background:var(--white)}.mapping-row label{display:flex;flex-direction:column;gap:6px;overflow-wrap:anywhere}.mapping-row label span{font-weight:600;font-size:14px}.mapping-row label small{font-size:10px;color:var(--muted)}.mapping-arrow{color:var(--green)}.mapping-row select{min-width:0;width:100%;font-size:13px}.comparison-result{padding:20px;border-radius:12px;background:var(--amber);margin:22px 0 18px;line-height:1.6;font-size:13px}.comparison-result>h4{font-size:17px;text-transform:none;letter-spacing:-.2px;margin:0 0 8px}.comparison-result>p{margin:8px 0}.comparison-positive{background:#dce9dc}.comparison-negative{background:#f0dfd4}.comparison-metrics{grid-template-columns:repeat(4,minmax(0,1fr));margin-top:18px}.comparison-changes{font-size:12px;padding-top:12px}.comparison-changes summary{cursor:pointer;font-weight:600}.comparison-changes li{margin:6px 0;overflow-wrap:anywhere}.comparison-carry{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-top:23px;border-top:1px solid var(--line);padding-top:20px}.comparison-carry>div:first-child{min-width:0}.digest{font-family:monospace;font-size:10px;line-height:1.7;overflow-wrap:anywhere;word-break:break-all;color:var(--muted)}@media(max-width:800px){.comparison-toolbar{flex-direction:column;align-items:stretch;gap:10px}.comparison-toolbar .case-picker{max-width:100%}.comparison-toolbar .text-button{text-align:left}.comparison-pair{grid-template-columns:1fr;gap:12px}.comparison-pair article{padding:17px}.mapping-row{grid-template-columns:minmax(0,.8fr) 14px minmax(0,1.2fr);gap:7px;padding:11px}.mapping-row select{padding:10px 5px;font-size:12px}.mapping-row label span{font-size:12px}.mapping-row label small{font-size:9px}.comparison-metrics{grid-template-columns:1fr 1fr}.comparison-carry{flex-direction:column;align-items:stretch}.comparison-result{padding:17px}.comparison>.primary{width:100%}.clue-row{padding:12px}}

/* The interface language is independent of the authored episode language. */
.toolbar{flex-wrap:wrap}.toolbar>.case-picker{min-width:0;flex:1 1 260px}.toolbar>.language-picker{flex:0 1 170px}.language-picker select{min-width:0;width:100%}.toolbar>.case-picker:not(.language-picker) select{width:100%}.tabs{flex-shrink:0}
@media(max-width:800px){.toolbar>.case-picker,.toolbar>.language-picker{flex:0 1 auto;width:100%}.tabs{width:100%}.tabs button{flex:1;min-width:0}.intro h1{overflow-wrap:anywhere}}

/* Draft feedback stays in the author view and leaves editor focus untouched. */
.draft-strip{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:0 0 18px;padding:12px 17px;border:1px solid var(--line);border-radius:12px;background:#eeefe5}.draft-strip p{font-size:12px;line-height:1.6;color:var(--muted);margin:0}.draft-strip p[data-state=conflict],.draft-strip p[data-state=invalid],.draft-strip p[data-state=incompatible],.draft-strip p[data-state=unavailable],.draft-strip p[data-state=loadFailed]{color:#8d3528}.draft-actions{display:flex;gap:16px;flex-shrink:0;flex-wrap:wrap}.draft-actions button{white-space:nowrap}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:800px){.draft-strip{align-items:flex-start;flex-direction:column;gap:3px}.draft-actions{gap:20px}}

/* Explicit action authoring uses the same revision checks as labels and clues. */
.action-editor{margin-top:21px;padding-top:21px;border-top:1px solid var(--line)}.action-editor label{display:block;font-size:13px;font-weight:600;margin-bottom:8px}.action-editor input{width:100%;min-width:0;font-size:20px}

/* Keep complete imported text readable inside constrained author/player layouts. */
.episode-heading > div { min-width: 0; }
.episode-heading h2,
.episode-heading p,
.comparison-pair h4,
.comparison-pair p,
.clues,
.hints p,
#semantic-changes { overflow-wrap: anywhere; }

/* Focused player sessions and author review. */
.playtest-toolbar{display:flex;justify-content:flex-end;padding-top:24px}.playtest-toolbar .language-picker{width:170px}.playtest-toolbar+.playtest-intro{padding-top:22px}
.playtest-author{margin-top:22px}.playtest-author-actions{display:flex;align-items:center;gap:22px;margin-bottom:15px}.playtest-review-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding:23px 0;margin:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}#playtest-review h4{font-size:19px;text-transform:none;letter-spacing:-.3px;margin-top:25px;line-height:1.4}#playtest-review{overflow-wrap:anywhere}.playtest-events{font-size:13px;line-height:1.7;margin-top:20px}.playtest-events summary{font-weight:600;cursor:pointer}.playtest-events ol{padding-left:24px}.playtest-events li{margin:8px 0}.playtest-page main{max-width:1140px}.playtest-intro{max-width:900px;padding-bottom:24px}.playtest-intro h1{font-family:Georgia,'Times New Roman',serif;font-weight:400;font-size:clamp(38px,4.8vw,58px);letter-spacing:-1.5px;line-height:1.12}.playtest-intro .lede{max-width:800px}.playtest-import{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin:15px 0 24px}.playtest-import label{font-size:14px;font-weight:600}.playtest-import input{max-width:100%;font-size:12px}.playtest-import p{flex-basis:100%}.playtest-page .panel h2,.playtest-record-strip h2{font-size:19px;font-weight:600;margin:0 0 9px;letter-spacing:-.4px}.playtest-page .section-title{margin-bottom:23px}.playtest-page .play-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}#playtest-answer-form{margin-top:30px}#playtest-answer-label{font-size:13px;font-weight:600}#playtest-solution{border-top:1px solid var(--line);padding-top:20px;margin-top:15px}#playtest-solution h3{font-size:15px}.playtest-record-strip{display:flex;align-items:center;justify-content:space-between;gap:30px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:27px 0;margin-top:24px}.playtest-record-strip>div{max-width:670px}.playtest-record-strip button{flex-shrink:0}#playtest-record-note{max-width:600px}#playtest-journal-summary{font-size:13px;color:var(--green)}#playtest-evidence-note{max-width:850px;margin-bottom:27px}@media(max-width:800px){.playtest-author-actions{flex-direction:column;align-items:stretch;gap:8px}.playtest-review-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.playtest-page .play-grid{grid-template-columns:1fr}.playtest-record-strip{flex-direction:column;align-items:stretch;gap:20px}.playtest-page .intro{padding-top:32px}.playtest-page .lede{font-size:14px}.playtest-page .panel{padding:22px}.playtest-page .answer-row{flex-direction:column}.playtest-intro h1{font-size:42px}.playtest-import{padding:20px}}
#playtest-title, #playtest-story, #playtest-solution { overflow-wrap: anywhere; }

/* A demonstrated conflict is author guidance, distinct from puzzle validation. */
.clue-conflict{margin:22px 0;padding:18px;border:1px solid #b76d54;border-radius:12px;background:var(--white);overflow-wrap:anywhere}.clue-conflict h4{margin-top:0}.clue-conflict ul{margin:16px 0 0;padding-left:20px}.clue-conflict li+li{margin-top:16px}.clue-conflict li p{margin:0 0 5px}.clue-row.in-conflict{outline:2px solid #a44e36;outline-offset:1px}.clue-conflict-badge{display:inline-block;grid-column:1/-1;font-size:12px;font-weight:600;color:#7c3222;overflow-wrap:anywhere}

/* Authored wording remains content, independent of interface language. */
.scene-editor{display:grid;grid-template-columns:minmax(190px,.8fr) minmax(0,2fr);gap:30px;margin-bottom:22px;align-items:start}.scene-editor>div,.scene-fields>div{min-width:0}.scene-editor .eyebrow{font-size:10px;line-height:1.5;margin:0 0 10px}.scene-editor h3{font-size:23px;margin:0 0 10px;letter-spacing:-.5px}.scene-fields{display:grid;gap:16px}.scene-fields label{display:block;font-size:13px;font-weight:600;margin-bottom:7px}.scene-fields input,.scene-fields textarea{width:100%;min-width:0}.scene-fields textarea{min-height:104px;line-height:1.55}.episode-heading #episode-story,#playtest-story{white-space:pre-wrap}
@media(max-width:800px){.scene-editor{grid-template-columns:1fr;gap:18px}.scene-editor h3{font-size:22px}.scene-fields textarea{min-height:128px}}

#episode-title-input{min-height:58px;font-size:20px;line-height:1.3}#episode-title,#playtest-title{white-space:pre-wrap}

/* Cohort review remains independent of the authored episode and single-record journey. */
.playtest-cohort{border-top:1px solid var(--line);padding-top:24px;margin-top:28px;min-width:0;overflow-wrap:anywhere}
.playtest-cohort-heading{display:flex;align-items:center;justify-content:space-between;gap:24px}.playtest-cohort-heading>div{min-width:0;max-width:650px}.playtest-cohort-heading button{flex-shrink:0;white-space:normal}.playtest-cohort-heading h4,#playtest-cohort-result>h4{font-size:19px;line-height:1.4;text-transform:none;letter-spacing:-.3px;margin:0 0 9px}
#playtest-cohort-status{margin:16px 0}#playtest-cohort-result{min-width:0}#playtest-cohort-result>h4{margin-top:24px}.playtest-cohort-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:20px 0;padding:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.playtest-cohort-metrics .metric{min-width:0}.playtest-cohort-metrics dt{font-size:12px;line-height:1.5;color:var(--muted)}.playtest-cohort-metrics dd{margin:8px 0 0;font-size:28px;line-height:1.1;font-weight:600;color:var(--green)}#playtest-cohort-result>.playtest-cohort-metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.playtest-cohort-groups{display:grid;gap:22px;margin-top:22px}.playtest-cohort-group{min-width:0;border:1px solid var(--line);padding:22px}.playtest-cohort-group h5{font-family:Georgia,'Times New Roman',serif;font-weight:400;font-size:24px;line-height:1.3;letter-spacing:-.4px;margin:0 0 10px}.playtest-cohort-group .digest{overflow-wrap:anywhere;word-break:break-word}.playtest-cohort-group .playtest-cohort-metrics{margin-bottom:0;border-bottom:0;padding-bottom:0}.playtest-cohort-limitations{padding-left:20px;max-width:900px;font-size:13px;line-height:1.7}.playtest-cohort-limitations li{margin:7px 0}
@media(max-width:800px){.playtest-cohort-heading{flex-direction:column;align-items:stretch;gap:12px}.playtest-cohort-heading button{width:100%}.playtest-cohort-metrics,#playtest-cohort-result>.playtest-cohort-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.playtest-cohort-group{padding:18px}.playtest-cohort-group h5{font-size:22px}}


/* Keep each player entry choice with its associated file control. */
.playtest-import-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;width:100%}.playtest-import-choice{display:flex;flex-direction:column;gap:12px;min-width:0}.playtest-import-choice input{width:100%;min-width:0}.playtest-import-choice label{line-height:1.5}@media(max-width:800px){.playtest-import-choices{grid-template-columns:1fr;gap:24px}}

/* Original episode entry and isolated handoff status. */
.original-entry{margin:-1rem 0 2rem;font-size:1rem}.original-entry a{color:var(--ink);text-underline-offset:.3em;font-weight:650}.author-handoff-notice{padding:1rem 1.2rem;margin:0 0 1rem;border:1px solid currentColor;border-radius:.35rem}

/* Begin a separate authored adaptation without hiding the copied-wording boundary. */
.adaptation-start{margin:0 0 22px}.adaptation-start>summary{font-size:18px;font-weight:600;cursor:pointer;line-height:1.45}.adaptation-options{display:flex;gap:20px;align-items:end;flex-wrap:wrap}.adaptation-options>.case-picker{flex:1;min-width:160px}.adaptation-options button{white-space:normal;max-width:100%}.adaptation-start .notice:empty{display:none}
@media(max-width:800px){.adaptation-options{flex-direction:column;align-items:stretch;gap:14px}.adaptation-options>.case-picker{min-width:0}.adaptation-options button{width:100%}}

.localization-notes{margin-top:1.5rem;padding-top:1rem;border-top:1px solid #d3d8ca}
.localization-notes summary{font-weight:700;cursor:pointer}
.localization-notes textarea{width:100%;box-sizing:border-box;resize:vertical;min-height:8rem;font:inherit}
.localization-notes label{display:block;margin:.8rem 0 .4rem;font-weight:600}
.localization-notes-actions{display:flex;flex-wrap:wrap;gap:.6rem}
.localization-notes-actions button{max-width:100%;white-space:normal}
#localization-notes-pair{overflow-wrap:anywhere}

